import 'package:flutter/material.dart';import 'package:sizer/sizer.dart';class ChipView extends StatelessWidget {  final String? text;  final IconData? icon;  final Color bgColor;  final Color textColor;  final bool isRemovable;  final VoidCallback? onRemove;  const ChipView({    super.key,    required this.text,    this.icon,    this.bgColor = Colors.grey,    this.textColor = Colors.black,    this.isRemovable = false,    this.onRemove,  });  @override  Widget build(BuildContext context) {    return Container(      padding: EdgeInsets.symmetric(horizontal: 3.w, vertical: 0.8.h),      decoration: BoxDecoration(        color: bgColor,        borderRadius: BorderRadius.circular(2.h),      ),      child: Row(        mainAxisSize: MainAxisSize.min,        children: [          if (icon != null)            Icon(              icon,              color: textColor,              size: 4.w,            ),          if (icon != null) SizedBox(width: 0.8.w),          Text(            text ?? 'N/A',            style: TextStyle(              fontSize: 9.5.sp,              color: textColor,              fontWeight: FontWeight.w600,            ),          ),          if (isRemovable) ...[            SizedBox(width: 1.w),            GestureDetector(              behavior: HitTestBehavior.opaque,              onTap: onRemove,              child: Padding(                padding: const EdgeInsets.all(2.0),                child: Icon(                  Icons.close,                  size: 14,                  color: textColor,                ),              ),            ),          ],        ],      ),    );  }}